mapper.select:
SELECT a.*
FROM article a
INNER JOIN follow f ON f.followed_id = a.author_id
WHERE f.follower_id = #{userId}
  AND a.status = 1
  AND a.is_deleted = 0
  AND a.author_id <> #{excludedAuthorId}

  AND a.id NOT IN

        #{shownArticleId}


ORDER BY a.create_time DESC, a.id DESC
LIMIT #{limit}

SELECT DISTINCT a.*
FROM article a
INNER JOIN article_tag at ON at.article_id = a.id
WHERE at.tag_id IN

    #{tagId}

  AND a.status = 1
  AND a.is_deleted = 0
  AND a.author_id <> #{excludedAuthorId}

  AND a.id NOT IN

        #{shownArticleId}


ORDER BY a.create_time DESC, a.id DESC
LIMIT #{limit}

SELECT a.* FROM article a WHERE a.status = 1 AND a.is_deleted = 0 AND a.author_id <> #{excludedAuthorId}
AND a.id NOT IN
#{shownArticleId}
ORDER BY (a.create_time >= DATE_SUB(NOW(), INTERVAL 7 DAY)) DESC, (COALESCE(a.view_count, 0) + COALESCE(a.like_count, 0) * 3 + COALESCE(a.collect_count, 0) * 5 + COALESCE(a.comment_count, 0) * 4) DESC, a.create_time DESC, a.id DESC LIMIT #{limit}

SELECT a.* FROM article a WHERE a.id IN
#{articleId}
AND a.status = 1 AND a.is_deleted = 0

SELECT a.* FROM article a WHERE a.status = 1 AND a.is_deleted = 0
AND (a.create_time < #{beforeCreateTime} OR (a.create_time = #{beforeCreateTime} AND a.id < #{beforeId}))
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit}
